"""Airflow DAG files generated by Schedule.Airflow, compared with saved files.

The expected files in tests/fixtures/dags/ are generated, not written by
hand. After an intended change to DAG generation, regenerate them with
DBIMPORT_UPDATE_EXPECTED_DAGS=1 and review the diff.
"""

import os
import re
from collections.abc import Callable
from pathlib import Path

import pytest
import sqlalchemy as sa
from ConfigReader import configuration
from Schedule import Airflow

pytestmark = pytest.mark.integration

EXPECTED_DIR = Path(__file__).resolve().parents[1] / "fixtures" / "dags"
UPDATE_EXPECTED = os.environ.get("DBIMPORT_UPDATE_EXPECTED_DAGS") == "1"
DAG_NAME = "DBImport_test"

Setup = Callable[[sa.Connection], None]


def _insert(conn: sa.Connection, table: str, **values: object) -> None:
    columns = ", ".join(values)
    params = ", ".join(f":{name}" for name in values)
    conn.execute(sa.text(f"INSERT INTO {table} ({columns}) VALUES ({params})"), values)


def _add_connection(conn: sa.Connection) -> None:
    """JDBC connection test_mysql with a configured driver path.

    DAG generation leaves out tables whose connection cannot be looked up.
    """
    conn.execute(
        sa.text(
            "UPDATE jdbc_connections_drivers SET classpath = :path "
            "WHERE database_type = 'MySQL' AND version = 'default'"
        ),
        {"path": "/opt/jdbc/mysql-connector-j.jar"},
    )
    _insert(
        conn,
        "jdbc_connections",
        dbalias="test_mysql",
        jdbc_url="jdbc:mysql://source.example:3306/sourcedb",
    )


def _add_tables(conn: sa.Connection, with_connection: bool = True) -> None:
    """One full and one incremental import table in Hive database testdb."""
    if with_connection:
        _add_connection(conn)
    common = {"hive_db": "testdb", "dbalias": "test_mysql", "source_schema": "src"}
    _insert(
        conn,
        "import_tables",
        hive_table="orders",
        source_table="orders",
        import_phase_type="full",
        etl_phase_type="truncate_insert",
        **common,
    )
    _insert(
        conn,
        "import_tables",
        hive_table="events",
        source_table="events",
        import_phase_type="incr",
        etl_phase_type="merge",
        incr_column="id",
        incr_mode="append",
        **common,
    )


def _add_dag(conn: sa.Connection, **extra: object) -> None:
    _insert(
        conn,
        "airflow_import_dags",
        dag_name=DAG_NAME,
        filter_hive="testdb.*",
        schedule_interval="None",
        **extra,
    )


def _default_dag(conn: sa.Connection) -> None:
    _add_tables(conn)
    _add_dag(conn)


def _import_and_etl_separate(conn: sa.Connection) -> None:
    _add_tables(conn)
    _add_dag(conn, run_import_and_etl_separate=1)


def _finish_all_stage1_first(conn: sa.Connection) -> None:
    _add_tables(conn)
    _add_dag(conn, finish_all_stage1_first=1)


def _custom_tasks(conn: sa.Connection) -> None:
    _default_dag(conn)
    _insert(
        conn,
        "airflow_tasks",
        dag_name=DAG_NAME,
        task_name="before_main_01",
        task_type="shell script",
        placement="before main",
        task_config="/usr/bin/sleep 1",
    )
    _insert(
        conn,
        "airflow_tasks",
        dag_name=DAG_NAME,
        task_name="in_main_01",
        task_type="Hive SQL",
        placement="in main",
        # Task ids of import tables are the Hive table names.
        task_dependency_upstream="orders",
        task_config="select 1",
    )
    _insert(
        conn,
        "airflow_tasks",
        dag_name=DAG_NAME,
        task_name="after_main_01",
        task_type="Trigger DAG",
        placement="after main",
        task_config="other_dag",
    )


SCENARIOS: dict[str, Setup] = {
    "default_import_dag": _default_dag,
    "import_and_etl_separate": _import_and_etl_separate,
    "finish_all_stage1_first": _finish_all_stage1_first,
    "custom_tasks": _custom_tasks,
}


def _undefined_task_references(dag_source: str) -> set[str]:
    """Names used in set_upstream/set_downstream that no task defines.

    compile() only checks syntax; Airflow would fail to load such a file.
    """
    used = set(re.findall(r"\.set_(?:up|down)stream\((\w+)\)", dag_source))
    defined = set(re.findall(r"(?m)^(\w+) = ", dag_source))
    return used - defined


def _generate(tmp_path: Path) -> str:
    Airflow.initialize().generateDAG(name=DAG_NAME, DAGFolder=str(tmp_path))
    return (tmp_path / f"{DAG_NAME}.py").read_text()


def _check_against_expected(name: str, generated: str) -> None:
    expected_file = EXPECTED_DIR / f"{name}.py.txt"
    if UPDATE_EXPECTED:
        expected_file.parent.mkdir(parents=True, exist_ok=True)
        expected_file.write_text(generated)
    assert generated == expected_file.read_text()


@pytest.mark.parametrize("name", sorted(SCENARIOS))
def test_generate_dag_writes_expected_file(
    clean_config_db: None, db_connection: sa.Connection, tmp_path: Path, name: str
) -> None:
    SCENARIOS[name](db_connection)

    generated = _generate(tmp_path)

    compile(generated, f"{DAG_NAME}.py", "exec")
    assert _undefined_task_references(generated) == set()
    _check_against_expected(name, generated)


def test_generate_dag_leaves_out_tables_whose_connection_is_missing(
    clean_config_db: None, db_connection: sa.Connection, tmp_path: Path
) -> None:
    _add_tables(db_connection, with_connection=False)
    _add_dag(db_connection)

    generated = _generate(tmp_path)

    assert "-t orders" not in generated
    assert "-t events" not in generated


def test_generate_dag_in_aws_mwaa_mode_writes_expected_file(
    clean_config_db: None,
    db_connection: sa.Connection,
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    monkeypatch.setitem(configuration.config["Airflow"], "airflow_mode", "aws_mwaa")
    _default_dag(db_connection)

    generated = _generate(tmp_path)

    compile(generated, f"{DAG_NAME}.py", "exec")
    assert _undefined_task_references(generated) == set()
    _check_against_expected("aws_mwaa", generated)
